ruleExplore.bookUrl:
@js:
var name = String(result);
var entry = String(baseUrl || '');
if (entry.indexOf('Research') >= 0 || entry.indexOf('yjlist') >= 0) {
    'http://www.ccg.org.cn/yjlist?fjcat=' + encodeURI(name) + '&zjcat=' + encodeURI(name);
} else if (entry.indexOf('activity') >= 0) {
    'http://www.ccg.org.cn/archives/category/activity';
} else {
    'http://www.ccg.org.cn/news';
}

ruleToc.chapterUrl:
@href
<js>
var raw=result; if(Array.isArray(raw))raw=raw[0]||""; var u=String(raw||"").trim();
if(u.charAt(0)==="["&&u.charAt(u.length-1)==="]")u=u.substring(1,u.length-1).trim();
if(u.indexOf('http')!==0){
  if(u.indexOf('//')===0)u='https:'+u;
  else if(u.indexOf('./')===0)u='http://www.ccg.org.cn/'+u.substring(2);
  else if(u.charAt(0)==='/')u='http://www.ccg.org.cn'+u;
  else u='http://www.ccg.org.cn/'+u;
}
result=u;
result;
</js>

